def shade(c, color):
    p=c._tc.get_or_add_tcPr(); e=OxmlElement('w:shd'); e.set(qn('w:fill'),color); p.append(e)
def header_row(row):
    p=row._tr.get_or_add_trPr(); e=OxmlElement('w:tblHeader'); e.set(qn('w:val'),'true'); p.append(e)
def page_num(p):
    r=p.add_run(); e=OxmlElement('w:fldSimple'); e.set(qn('w:instr'),'PAGE'); r._r.append(e)
def cell(c, value, bold=False, color=None):
    c.text=''; p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); r=p.add_run(str(value)); r.bold=bold
    if color: r.font.color.rgb=RGBColor.from_string(color)
    c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def grid(headers, rows, widths=None):
    t=d.add_table(rows=1, cols=len(headers)); t.style='Table Grid'; t.autofit=False; t.alignment=WD_TABLE_ALIGNMENT.CENTER; header_row(t.rows[0])
    for i,x in enumerate(headers):
        cell(t.rows[0].cells[i],x,True,'FFFFFF'); shade(t.rows[0].cells[i],'1F4E79')
        if widths: t.rows[0].cells[i].width=Inches(widths[i])
    for row in rows:
        cs=t.add_row().cells
        for i,x in enumerate(row):
            cell(cs[i],x)
            if widths: cs[i].width=Inches(widths[i])
    apply_table_geometry(t, column_widths_from_weights(widths or [1] * len(headers), 9360))
    d.add_paragraph('')
def note(tag, text, fill='EAF2F8'):
    t=d.add_table(rows=1, cols=1); t.autofit=False; header_row(t.rows[0]); c=t.cell(0,0); shade(c,fill); p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); r=p.add_run(tag+'  '); r.bold=True; r.font.color.rgb=RGBColor(31,78,121); p.add_run(text); apply_table_geometry(t, [9360]); d.add_paragraph('')
def h1(s): d.add_heading(s,1)
def h2(s): d.add_heading(s,2)
def h3(s): d.add_heading(s,3)
def para(s): d.add_paragraph(s)
def bullets(xs):
    for x in xs: d.add_paragraph(x,style='List Bullet')
def steps(xs):
    for x in xs: d.add_paragraph(x,style='List Number')
def page(name,purpose,when,how,track,fields=None,related=None,important=None):
    h2(name); para(purpose); h3('When to use it'); para(when); h3('How to use it'); steps(how)
    if fields: h3('Fields, lists and actions'); grid(['Item','What it does'],fields,[2.05,4.25])
    h3('Where to track the result'); para(track)
    if related: h3('Related pages'); para(related)
    if important: note('Important',important,'FFF4E5')

d=Document(); sec=d.sections[0]; sec.top_margin=sec.bottom_margin=Inches(.85); sec.left_margin=sec.right_margin=Inches(.85); sec.header_distance=Inches(.35); sec.footer_distance=Inches(.35)
for n,sz,col,b,a in [('Normal',10.5,'000000',0,5),('Title',30,'1F4E79',0,12),('Heading 1',17,'1F4E79',16,8),('Heading 2',13,'2E74B5',12,5),('Heading 3',11,'1F4E79',8,4)]:
    s=d.styles[n]; s.font.name='Calibri'; s.font.size=Pt(sz); s.font.color.rgb=RGBColor.from_string(col); s.font.bold=n!='Normal'; s.paragraph_format.space_before=Pt(b); s.paragraph_format.space_after=Pt(a); s.paragraph_format.line_spacing=1.1
for n in ['List Bullet','List Number']:
    d.styles[n].font.name='Calibri'; d.styles[n].font.size=Pt(10.5); d.styles[n].paragraph_format.space_after=Pt(3)
hp=sec.header.paragraphs[0]; hp.text='MAAMULPRO V2  |  CLIENT USER MANUAL'; hp.runs[0].font.color.rgb=RGBColor(31,78,121); hp.runs[0].font.bold=True
fp=sec.footer.paragraphs[0]; fp.alignment=WD_ALIGN_PARAGRAPH.RIGHT; fp.add_run('MaamulPro V2 Client User Manual  |  Page '); page_num(fp)

p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(110); r=p.add_run('MaamulPro V2'); r.font.size=Pt(34); r.bold=True; r.font.color.rgb=RGBColor(31,78,121)
p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run('Client User Manual'); r.font.size=Pt(24); r.bold=True; r.font.color.rgb=RGBColor(46,116,181)
p=d.add_paragraph('Overview | People & finance | Construction | Real estate | Materials | Administration'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.runs[0].font.size=Pt(12); p.runs[0].font.color.rgb=RGBColor(89,89,89)
