grid(['Section'],[(x,) for x in ['1. About this guide','2. Signing in and access','3. Navigation and Overview','4. People & finance','5. Construction','6. Real estate','7. Materials','8. Reports and Administration','9. End-to-end workflows','10. Quick guides and troubleshooting','11. Glossary']],[6.3])
